import{_ as r,a0 as a,w as d,s as i,ao as m,I as p,x as e,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"三個快速便捷的命令列小貼士 | LCTT x X-CMD","titleTemplate":false,"description":"三個快速便捷的命令列小貼士 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"三個快速便捷的命令列小貼士 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"三個快速便捷的命令列小貼士 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Quick-n-easy command-line tips","title":"三個快速便捷的命令列小貼士","tag":"201310","desc":""},"relativePath":"201310/Quick-n-easy command-line tips.md","filePath":"[post].md"}'),l={name:"201310/Quick-n-easy command-line tips.md"};function u(c,t,g,f,T,x){const n=a("Link");return d(),i("div",null,[t[11]||(t[11]=m(`<h1 id="三個快速便捷的命令列小貼士" tabindex="-1">三個快速便捷的命令列小貼士 <a class="header-anchor" href="#三個快速便捷的命令列小貼士" aria-label="Permalink to “三個快速便捷的命令列小貼士”">​</a></h1><p>最近幾周裏，我總是收到人們詢問一些快速零散的問題。有時候一個人是在尋找一個有幫助的建議，或者一個具體的命令，或者一個命令列捷徑，以完成一個特定的任務。本篇將介紹最近人們向我提出的三個問題，以及完成這些任務的簡單方法。</p><p>###第一個場景</p><p><strong>我們要找到那些在過去的一個月中被改動過的文件，並將他們從當前的位置複製到另一個目錄中去。</strong></p><p>在這種情況下，能否精確的解決取決於你複製文件的時候是否保持了原來的文件樹結構，還是你僅僅只是把所有文件全部複製到了一個指定的地方。如果我們只是想把所有的文件保存到一個文件夾中，或許這樣做是為了將這些文件歸檔，那麼我們可以使用find這條命令。通過使用find命令，我們能夠根據文件被修改的時間查找到他們的位置，然後複製他們到指定的地方。這條命令看起來是這樣：</p><pre><code>find Documents -mtime -30 -exec cp &quot;{}&quot; Backup \\;
</code></pre><p>上面這條命令會在Documents文件夾中查找在過去30天內被修改過的文件。這些文件之後將會被複制到另一個叫Backup的目錄中去。<strong>find</strong>命令將會通過調用<strong>cp</strong>命令來執行復制這一操作。通過修改<strong>mtime</strong>這條參數，我們可以查找到最近某個時間內被修改過的文件，在上面這個例子中它被設定為在過去的30天內。</p><p>更多的時候，我們會想要在把文件複製到目標文件夾後，仍然能夠保留源文件夾的目錄結構。很多時候，人們都希望兩個文件夾的內容同步，然後他們會運行一個腳本來使他們保持一致。這種情況下，我們可能會用到<strong>rsync</strong>這條命令了。這個工具會把新文件、修改過的文件從一個複製到另一個目錄中去，同時保持源目錄的展示結構：</p><pre><code>rsync -a Documents/ Backup
</code></pre><p>上面的例子，它會先找到哪些文件在Documents中和Backup中都存在，以便不再複製這些不必要的文件。</p><p>###第二個場景</p><p><strong>有一個我們都會做的很普遍的工作，就是在一個文本文件中找到一個單詞，然後用另一個單詞把這個詞在文本中的所有實例都替換掉。</strong></p><p>比如，假設我有一個文檔中提到一個人名叫“Becky”，但是我後來決定還是用稍微正式點的稱呼“Rebecca”為好。對文件中的這個簡單的改動，下面這條命令會起到作用：</p><pre><code>perl -pi -e &#39;s/Becky/Rebecca/&#39; mydocument.txt
</code></pre><p>這條微型的Perl腳本會查詢文檔中所有“Becky”的實例，並且將之改為“Rebecca”。程序首先讀取名為mydocument.txt這個要改動的文檔，待修改完畢後再保存回去。</p><p>###第三個場景</p><p><strong>一個普遍關注的問題是，在一個硬盤要給別人或者被扔掉之前，需要對其中存儲的敏感數據做些什麼。</strong></p><p>有些人會在電腦裏保存一些銀行的業務數據或者税務信息，那麼這些數據最好在你的硬盤被轉手到別人之前被徹底清理掉。現在有一些方法和工具可以讓你使用。我最喜歡的一個是<strong>shred</strong>這條命令，它不僅能對單一文件進行處理，同樣也能對整個設備進行處理。要重寫一個文件裏面的內容，我們可以這樣運行<strong>shred</strong>：</p><pre><code>shred mytaxes.odt
</code></pre><p>上面這個例子中，它會移除文件裏存的內容，但並不會把文件本身從硬盤中刪除掉。如果要清除文件的內容同時刪除掉這個文件，我們可以這樣運行：</p><pre><code>shred -u mytaxes.odt
</code></pre><p>需要強調的一點是，<strong>shred</strong>並不是在所有的文件系統中都能正常運行，尤其是那些帶有日誌功能的比較新的文件系統。在<strong>shred</strong>的操作手冊中寫明瞭哪些文件系統運行這個程序的時候會出問題。當處理敏感數據的時候，最好的方法也許是清除掉整張硬盤。<strong>shred</strong>同樣也能辦到。下面這個例子中，顯示瞭如何移除掉我們電腦中第一塊硬盤內的所有數據。使用這條命令一定要非常小心：</p><pre><code>shred /dev/sda
</code></pre><hr>`,24)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),s(n,{href:"http://distrowatch.com/weekly.php?issue=20130923"},{default:o(()=>[...t[0]||(t[0]=[e("http://distrowatch.com/weekly.php?issue=20130923",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[2]||(t[2]=[e("LCTT",-1)])]),_:1}),t[5]||(t[5]=e(" 原創翻譯，",-1)),s(n,{href:"http://linux.cn/portal.php"},{default:o(()=>[...t[3]||(t[3]=[e("Linux中國",-1)])]),_:1}),t[6]||(t[6]=e(" 榮譽推出",-1))]),p("p",null,[t[9]||(t[9]=e("譯者：",-1)),s(n,{href:"http://linux.cn/space/markvv"},{default:o(()=>[...t[7]||(t[7]=[e("markvv",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),s(n,{href:"http://linux.cn/space/wxy"},{default:o(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})])])}const h=r(l,[["render",u]]);export{C as __pageData,h as default};
